def esc(t):
    return t.replace("\\", "\\\\").replace('"', '\\"')

ORDER = ['VM_I18N_TITLE', 'VM_I18N_ROW_SD2VITA', 'VM_I18N_ROW_INTERNAL', 'VM_I18N_ROW_HUD', 'VM_I18N_ROW_MEMCARD', 'VM_I18N_ROW_VERIFY', 'VM_I18N_HINT_SD2VITA', 'VM_I18N_HINT_INTERNAL', 'VM_I18N_HINT_HUD', 'VM_I18N_HINT_MEMCARD', 'VM_I18N_HINT_VERIFY', 'VM_I18N_ITEM_HUD_OFF', 'VM_I18N_ITEM_HUD_COMPACT', 'VM_I18N_ITEM_HUD_EXTENDED', 'VM_I18N_ST_FALLBACK', 'VM_I18N_ST_NO_BUFFER', 'VM_I18N_ST_FIRMWARE', 'VM_I18N_ST_HOOKS', 'VM_I18N_ST_SAFE', 'VM_I18N_ST_NO_KERNEL', 'VM_I18N_ST_SLOW', 'VM_I18N_TITLE_ADVANCED', 'VM_I18N_ROW_LOG', 'VM_I18N_HINT_LOG', 'VM_I18N_ROW_HUD_STYLE', 'VM_I18N_HINT_HUD_STYLE', 'VM_I18N_ITEM_STYLE_CLASSIC', 'VM_I18N_ITEM_STYLE_PSVSHELL', 'VM_I18N_ROW_SAFE', 'VM_I18N_HINT_SAFE_ON', 'VM_I18N_HINT_SAFE_OFF', 'VM_I18N_MSG_SAFE_OK', 'VM_I18N_MSG_SAFE_ERR']
assert set(ORDER) == set(T), set(ORDER) ^ set(T)
out = ["/* Generated by tools/gen_i18n.py - edit that, not this file. */",
       "/* clang-format off */"]
for k in ORDER:
    row = T[k]
    missing = [l for l in LANGS if l not in row]
    assert not missing, (k, missing)
    out.append(f"[{k}] = {{")
    for l in LANGS:
        out.append(f'\t"{esc(row[l])}",   /* {l} */')
    out.append("},")
open("settings_app/vitamemio_i18n_table.h", "w").write("\n".join(out) + "\n")
print("wrote", len(ORDER), "strings x", len(LANGS), "languages")
